CREATE DATABASE IF NOT EXISTS cafe_elfirdaous CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cafe_elfirdaous;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, role ENUM('admin','cashier') NOT NULL DEFAULT 'cashier', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NULL) ENGINE=InnoDB;
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NULL, name VARCHAR(150) NOT NULL, cost DECIMAL(10,2) NOT NULL DEFAULT 0, price DECIMAL(10,2) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE customer_tiers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0, first_order_points INT NOT NULL DEFAULT 0, order_threshold INT NOT NULL DEFAULT 5, threshold_points INT NOT NULL DEFAULT 0, point_value DECIMAL(8,2) NOT NULL DEFAULT 0.10) ENGINE=InnoDB;
CREATE TABLE customers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, phone VARCHAR(40) NULL, tier_id INT NULL, balance DECIMAL(10,2) NOT NULL DEFAULT 0, points INT NOT NULL DEFAULT 0, total_purchases DECIMAL(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tier_id) REFERENCES customer_tiers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE daily_customer_orders (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, order_date DATE NOT NULL, order_count INT NOT NULL DEFAULT 0, UNIQUE KEY customer_day(customer_id,order_date), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE sales (id INT AUTO_INCREMENT PRIMARY KEY, invoice_no VARCHAR(40) NOT NULL UNIQUE, customer_id INT NULL, user_id INT NOT NULL, subtotal DECIMAL(10,2) NOT NULL, discount DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(10,2) NOT NULL, paid DECIMAL(10,2) NOT NULL DEFAULT 0, points_redeemed INT NOT NULL DEFAULT 0, points_earned INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE sale_items (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NULL, product_name VARCHAR(150) NOT NULL, quantity DECIMAL(10,2) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, unit_cost DECIMAL(10,2) NOT NULL, FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, user_id INT NOT NULL, type ENUM('debt_payment','deposit','adjustment') NOT NULL, amount DECIMAL(10,2) NOT NULL, balance_after DECIMAL(10,2) NOT NULL, note VARCHAR(255) NULL, created_at DATETIME NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE loyalty_points (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, sale_id INT NULL, type ENUM('earned','redeemed','manual_add','manual_deduct') NOT NULL, points INT NOT NULL, balance_after INT NOT NULL, note VARCHAR(255) NULL, created_at DATETIME NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE expense_categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE expenses (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NULL, user_id INT NOT NULL, title VARCHAR(180) NOT NULL, amount DECIMAL(10,2) NOT NULL, expense_date DATE NOT NULL, note TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES expense_categories(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
